-- Add columns from the isolated World schema, retaining legacy source columns and rows.
ALTER TABLE `creature` ADD COLUMN `wander_distance` float NOT NULL DEFAULT 0, ADD COLUMN `walk_mode` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `ScriptName` varchar(64) NOT NULL DEFAULT '', ADD COLUMN `phaseid` int(10) unsigned NOT NULL DEFAULT 0, ADD COLUMN `phasegroup` int(10) unsigned NOT NULL DEFAULT 0;
ALTER TABLE `creature_addon` ADD COLUMN `StandState` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `AnimTier` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `VisFlags` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `SheathState` tinyint(3) unsigned NOT NULL DEFAULT 1, ADD COLUMN `PvPFlags` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `aiAnimKit` int(10) unsigned NOT NULL DEFAULT 0, ADD COLUMN `movementAnimKit` int(10) unsigned NOT NULL DEFAULT 0, ADD COLUMN `meleeAnimKit` int(10) unsigned NOT NULL DEFAULT 0, ADD COLUMN `visibilityDistanceType` tinyint(3) unsigned NOT NULL DEFAULT 0;
ALTER TABLE `creature_equip_template` ADD COLUMN `CreatureID` mediumint(8) unsigned NOT NULL DEFAULT 0, ADD COLUMN `ItemID1` mediumint(8) unsigned NOT NULL DEFAULT 0, ADD COLUMN `ItemID2` mediumint(8) unsigned NOT NULL DEFAULT 0, ADD COLUMN `ItemID3` mediumint(8) unsigned NOT NULL DEFAULT 0;
ALTER TABLE `creature_template` ADD COLUMN `faction` smallint(5) unsigned NOT NULL DEFAULT 0, ADD COLUMN `femaleName` char(100) NOT NULL DEFAULT '';
ALTER TABLE `creature_template_addon` ADD COLUMN `StandState` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `AnimTier` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `VisFlags` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `SheathState` tinyint(3) unsigned NOT NULL DEFAULT 1, ADD COLUMN `PvPFlags` tinyint(3) unsigned NOT NULL DEFAULT 0, ADD COLUMN `aiAnimKit` int(10) unsigned NOT NULL DEFAULT 0, ADD COLUMN `movementAnimKit` int(10) unsigned NOT NULL DEFAULT 0, ADD COLUMN `meleeAnimKit` int(10) unsigned NOT NULL DEFAULT 0, ADD COLUMN `visibilityDistanceType` tinyint(3) unsigned NOT NULL DEFAULT 0;
