ALTER TABLE `game_event` ADD COLUMN `holidayStage` tinyint(3) unsigned NOT NULL DEFAULT 0;
ALTER TABLE `gameobject` ADD COLUMN `ScriptName` varchar(64) NOT NULL DEFAULT '', ADD COLUMN `phasegroup` int(10) unsigned NOT NULL DEFAULT 0;
