UPDATE creature_template SET faction=faction_A, femaleName=name;
UPDATE creature SET wander_distance=spawndist;
UPDATE creature_text SET CreatureID=entry;
UPDATE creature_equip_template SET CreatureID=entry,ItemID1=itemEntry1,ItemID2=itemEntry2,ItemID3=itemEntry3;
UPDATE creature_addon SET StandState=(bytes1 & 255),AnimTier=((bytes1 >> 8) & 255),VisFlags=((bytes1 >> 16) & 255),SheathState=(bytes2 & 255),PvPFlags=((bytes2 >> 8) & 255);
UPDATE creature_template_addon SET StandState=(bytes1 & 255),AnimTier=((bytes1 >> 8) & 255),VisFlags=((bytes1 >> 16) & 255),SheathState=(bytes2 & 255),PvPFlags=((bytes2 >> 8) & 255);
