UPDATE gossip_menu_option SET MenuID=menu_id,OptionID=id,OptionIcon=option_icon,OptionText=option_text,OptionType=option_id,OptionNpcFlag=npc_option_npcflag,ActionMenuID=action_menu_id,ActionPoiID=action_poi_id,BoxCoded=box_coded,BoxMoney=box_money,BoxText=box_text;
UPDATE points_of_interest SET ID=entry,PositionX=x,PositionY=y,Importance=data,Name=icon_name;
UPDATE quest_poi SET Idx1=id,ObjectiveIndex=objIndex,Floor=FloorId,Priority=unk3,Flags=unk4;
UPDATE quest_poi_points SET Idx1=id,Idx2=idx;
